var el = root.querySelector('.trm4-prompt-exit-type');
var list = ['git push origin main', 'docker compose up -d', 'pnpm test --watch'];
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) { el.textContent = list[0]; return; }
var ci = 0, i = 0, back = false;
function step() {
  var s = list[ci], d = 58;
  if (back) { i--; d = 26; if (i <= 0) { i = 0; back = false; ci = (ci + 1) % list.length; d = 420; } }
  else { i++; if (i >= s.length) { i = s.length; back = true; d = 1700; } }
  el.textContent = s.slice(0, i);
  setTimeout(step, d);
}
setTimeout(step, 500);

