var rows = root.querySelectorAll('.trm4-cmd-palette-row');
var count = root.querySelector('.trm4-cmd-palette-count');
if (!rows.length) return;
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) return;
var i = 0;
setInterval(function () {
  rows[i].classList.remove('trm4-cmd-palette-on');
  i = (i + 1) % rows.length;
  rows[i].classList.add('trm4-cmd-palette-on');
  count.textContent = (i + 1) + ' / 128';
}, 1400);

var rows = root.querySelectorAll('.trm4-git-status-row');
var stg = root.querySelector('.trm4-git-status-stg');
var ah = root.querySelector('.trm4-git-status-ah');
var states = [[' ', 'M', 'M'], ['?', '?', 'A'], [' ', 'M', 'M'], [' ', 'D', 'D']];
function paint(n, staged) {
  var r = rows[n], st = states[n];
  var x = r.querySelector('.trm4-git-status-x'), y = r.querySelector('.trm4-git-status-y');
  x.textContent = staged ? st[2] : st[0];
  y.textContent = staged ? ' ' : st[1];
  x.className = 'trm4-git-status-x' + (!staged && st[0] === '?' ? ' trm4-git-status-unt' : '');
}
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) { for (var k = 0; k < rows.length; k++) paint(k, false); return; }
var n = 0;
function tick() {
  if (n < rows.length) {
    paint(n, true);
    rows[n].classList.add('trm4-git-status-flash');
    (function (r) { setTimeout(function () { r.classList.remove('trm4-git-status-flash'); }, 700); })(rows[n]);
    n++;
    stg.textContent = n + ' staged';
    ah.textContent = '↑' + (2 + (n === rows.length ? 1 : 0));
    setTimeout(tick, 950);
  } else {
    setTimeout(function () {
      for (var k = 0; k < rows.length; k++) paint(k, false);
      stg.textContent = '0 staged';
      ah.textContent = '↑2';
      n = 0;
      setTimeout(tick, 900);
    }, 2200);
  }
}
for (var k = 0; k < rows.length; k++) paint(k, false);
setTimeout(tick, 800);

var lines = root.querySelectorAll('.trm4-diff-gutter-ln');
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function showAll() { for (var i = 0; i < lines.length; i++) lines[i].classList.add('trm4-diff-gutter-in'); }
if (rm) { showAll(); return; }
function run() {
  for (var i = 0; i < lines.length; i++) lines[i].classList.remove('trm4-diff-gutter-in');
  for (var j = 0; j < lines.length; j++) {
    (function (n) { setTimeout(function () { lines[n].classList.add('trm4-diff-gutter-in'); }, 120 + n * 130); })(j);
  }
  setTimeout(run, 6800);
}
run();

var spin = root.querySelector('.trm4-pkg-install-spin');
var msg = root.querySelector('.trm4-pkg-install-msg');
var pct = root.querySelector('.trm4-pkg-install-pct');
var fill = root.querySelector('.trm4-pkg-install-fill');
var cnt = root.querySelector('.trm4-pkg-install-cnt');
var rate = root.querySelector('.trm4-pkg-install-rate');
var log = root.querySelector('.trm4-pkg-install-log');
var stat = root.querySelector('.trm4-pkg-install-stat');
var frames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
var pkgs = [['@tanstack/query', '5.51.1'], ['zod', '3.23.8'], ['@tanstack/core', '5.51.0'], ['tslib', '2.6.3']];
function add(name, ver, ms) {
  var li = document.createElement('li');
  li.className = 'trm4-pkg-install-item trm4-pkg-install-new';
  var t = document.createElement('span');
  t.className = 'trm4-pkg-install-tick';
  t.textContent = '+ ';
  var n = document.createElement('span');
  n.className = 'trm4-pkg-install-nm';
  n.textContent = name + ' ';
  li.appendChild(t); li.appendChild(n);
  li.appendChild(document.createTextNode(ver + '  ' + ms + 'ms'));
  log.insertBefore(li, log.firstChild);
  while (log.children.length > 4) log.removeChild(log.lastChild);
}
function finish() {
  spin.textContent = '✓';
  stat.classList.add('trm4-pkg-install-ok');
  msg.textContent = 'done in 3.4s';
  pct.textContent = '100%';
  fill.style.width = '100%';
  cnt.textContent = 'resolved 64, reused 61';
  rate.textContent = '+64 packages';
}
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) { for (var i = 0; i < 3; i++) add(pkgs[i][0], pkgs[i][1], 40 + i * 9); finish(); return; }
var f = 0;
setInterval(function () { if (!stat.classList.contains('trm4-pkg-install-ok')) { f = (f + 1) % frames.length; spin.textContent = frames[f]; } }, 80);
var p = 0, pi = 0;
function tick() {
  p += 3 + Math.random() * 7;
  if (p >= 100) {
    p = 100; finish();
    setTimeout(function () {
      p = 0; pi = 0;
      stat.classList.remove('trm4-pkg-install-ok');
      msg.textContent = 'resolving dependencies…';
      pct.textContent = '0%'; fill.style.width = '0%';
      cnt.textContent = 'resolved 0, reused 0'; rate.textContent = '0.0 MB/s';
      while (log.firstChild) log.removeChild(log.firstChild);
      setTimeout(tick, 500);
    }, 2600);
    return;
  }
  var w = Math.round(p);
  pct.textContent = w + '%';
  fill.style.width = w + '%';
  msg.textContent = w < 30 ? 'resolving dependencies…' : (w < 70 ? 'fetching tarballs…' : 'linking node_modules…');
  cnt.textContent = 'resolved ' + Math.round(w * 0.64) + ', reused ' + Math.round(w * 0.61);
  rate.textContent = (2 + Math.random() * 3).toFixed(1) + ' MB/s';
  if (pi < pkgs.length && w > (pi + 1) * 20) { add(pkgs[pi][0], pkgs[pi][1], 30 + Math.round(Math.random() * 60)); pi++; }
  setTimeout(tick, 220);
}
setTimeout(tick, 600);

