var files = root.querySelectorAll('.trm4-test-summary-f');
var clock = root.querySelector('.trm4-test-summary-clock');
var ok = root.querySelector('.trm4-test-summary-ok');
var bad = root.querySelector('.trm4-test-summary-bad');
var err = root.querySelector('.trm4-test-summary-err');
var data = [[12, 0, 318], [8, 0, 204], [3, 2, 1020]];
var frames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧'];
function reset() {
  for (var i = 0; i < files.length; i++) {
    files[i].className = 'trm4-test-summary-f';
    files[i].querySelector('.trm4-test-summary-mk').textContent = '·';
  }
  ok.textContent = '0 passed'; bad.textContent = '0 failed';
  clock.textContent = '0.00s'; err.classList.remove('trm4-test-summary-show');
}
function done(i, p, f) {
  files[i].className = 'trm4-test-summary-f trm4-test-summary-live ' + (f ? 'trm4-test-summary-fail' : 'trm4-test-summary-pass');
  files[i].querySelector('.trm4-test-summary-mk').textContent = f ? '✗' : '✓';
  ok.textContent = p + ' passed'; bad.textContent = f + ' failed';
}
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) { done(0, 12, 0); done(1, 20, 0); done(2, 23, 2); clock.textContent = '1.94s'; err.classList.add('trm4-test-summary-show'); return; }
var idx = 0, pass = 0, failn = 0, t = 0, sp = 0, spinner = null;
function runOne() {
  if (idx >= data.length) {
    err.classList.add('trm4-test-summary-show');
    setTimeout(function () { reset(); idx = 0; pass = 0; failn = 0; t = 0; setTimeout(runOne, 700); }, 2800);
    return;
  }
  var d = data[idx];
  files[idx].classList.add('trm4-test-summary-live');
  var mk = files[idx].querySelector('.trm4-test-summary-mk');
  spinner = setInterval(function () { sp = (sp + 1) % frames.length; mk.textContent = frames[sp]; }, 80);
  setTimeout(function () {
    clearInterval(spinner);
    pass += d[0]; failn += d[1]; t += d[2];
    done(idx, pass, failn);
    clock.textContent = (t / 1000).toFixed(2) + 's';
    idx++;
    setTimeout(runOne, 220);
  }, 700 + idx * 180);
}
reset();
setTimeout(runOne, 600);

