var tabs = root.querySelectorAll('.trm4-session-tabs-tab');
var pane = root.querySelector('.trm4-session-tabs-pane');
var panes = [
  ['<span class="trm4-session-tabs-p">❯</span> bun run dev', '<span class="trm4-session-tabs-g">→</span> listening on <span class="trm4-session-tabs-a">:3000</span>', '<span class="trm4-session-tabs-d">GET</span> /v1/health <span class="trm4-session-tabs-g">200</span> 3ms', '<span class="trm4-session-tabs-d">GET</span> /v1/user <span class="trm4-session-tabs-g">200</span> 11ms'],
  ['<span class="trm4-session-tabs-d">12:04:09</span> <span class="trm4-session-tabs-a">INFO</span> cache warm', '<span class="trm4-session-tabs-d">12:04:11</span> <span class="trm4-session-tabs-w">WARN</span> slow query 412ms', '<span class="trm4-session-tabs-d">12:04:12</span> <span class="trm4-session-tabs-a">INFO</span> retry id=8f2', '<span class="trm4-session-tabs-d">12:04:14</span> <span class="trm4-session-tabs-g">OK</span> flushed 128 rows'],
  ['<span class="trm4-session-tabs-d">  1</span> export const TTL = 900;', '<span class="trm4-session-tabs-d">  2</span> export function sign(p) {', '<span class="trm4-session-tabs-d">  3</span>   return jwt.sign(p);', '<span class="trm4-session-tabs-g">-- INSERT --</span>  <span class="trm4-session-tabs-d">3,14</span>']
];
function render(i) {
  pane.innerHTML = '';
  for (var n = 0; n < panes[i].length; n++) {
    var d = document.createElement('div');
    d.className = 'trm4-session-tabs-line';
    d.innerHTML = panes[i][n];
    pane.appendChild(d);
  }
}
function select(i) {
  for (var n = 0; n < tabs.length; n++) {
    tabs[n].classList.toggle('trm4-session-tabs-on', n === i);
    tabs[n].querySelector('.trm4-session-tabs-bell').classList.toggle('trm4-session-tabs-ring', n === 1 && i !== 1);
  }
  render(i);
}
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
select(0);
if (rm) return;
var i = 0;
setInterval(function () { i = (i + 1) % tabs.length; select(i); }, 3200);

