var typed = root.querySelector('.trm4-autosuggest-typed');
var ghost = root.querySelector('.trm4-autosuggest-ghost');
var rows = root.querySelectorAll('.trm4-autosuggest-h');
var hist = ['git commit --amend --no-edit', 'git checkout -b feat/tokens', 'gh pr create --fill --draft', 'pnpm dlx tsx db/seed.ts'];
function paint(pre, taken) {
  typed.textContent = pre;
  typed.className = 'trm4-autosuggest-typed' + (taken ? ' trm4-autosuggest-taken' : '');
  var best = -1;
  for (var i = 0; i < hist.length; i++) { if (pre && hist[i].indexOf(pre) === 0) { best = i; break; } }
  ghost.textContent = (!taken && best >= 0) ? hist[best].slice(pre.length) : '';
  for (var j = 0; j < rows.length; j++) {
    var match = pre && hist[j].indexOf(pre) === 0;
    rows[j].className = 'trm4-autosuggest-h' + (match ? ' trm4-autosuggest-hit' : '') + (j === best ? ' trm4-autosuggest-sel' : '');
    var c = rows[j].querySelector('.trm4-autosuggest-cmd');
    c.innerHTML = '';
    if (match) {
      var m = document.createElement('span');
      m.className = 'trm4-autosuggest-mt';
      m.textContent = pre;
      c.appendChild(m);
      c.appendChild(document.createTextNode(hist[j].slice(pre.length)));
    } else { c.textContent = hist[j]; }
  }
}
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) { paint('git com', false); return; }
var stems = ['git com', 'git ch', 'gh p'];
var si = 0, i = 0, phase = 0;
function step() {
  var s = stems[si];
  if (phase === 0) {
    i++;
    paint(s.slice(0, i), false);
    if (i >= s.length) { phase = 1; setTimeout(step, 1200); return; }
    setTimeout(step, 95);
  } else if (phase === 1) {
    var full = '';
    for (var k = 0; k < hist.length; k++) { if (hist[k].indexOf(s) === 0) { full = hist[k]; break; } }
    paint(full, true);
    phase = 2;
    setTimeout(step, 1500);
  } else {
    phase = 0; i = 0; si = (si + 1) % stems.length;
    paint('', false);
    setTimeout(step, 550);
  }
}
paint('', false);
setTimeout(step, 700);
